--[[
    Nam Hub 1.0.0 - single-file build
    Generated by tools/build.py. Do not edit; edit src/ and rebuild.
]]

local genv = (getgenv and getgenv()) or _G
if genv.__ScriptHub and genv.__ScriptHub.Unload then pcall(genv.__ScriptHub.Unload) end

local __sources = {}
__sources["src/core"] = [=[
--[[
    Script Hub - core framework
    ===========================
    Responsibilities:
      * work out which game the player is in,
      * pick the matching entry out of src/registry.lua,
      * build the Fluent window and the shared "Hub" tab,
      * hand each game module a context object and run it,
      * track everything the module creates so Unload really unloads.

    A game module never creates its own window. It gets ctx.Tab and uses
    ctx.Connect / ctx.Spawn / ctx.OnUnload so the hub can clean up after it.
]]

local Core = {}

local FLUENT_URL    = "https://github.com/dawid-scripts/Fluent/releases/latest/download/main.lua"
local SAVEMGR_URL   = "https://raw.githubusercontent.com/dawid-scripts/Fluent/master/Addons/SaveManager.lua"
local INTERFACE_URL = "https://raw.githubusercontent.com/dawid-scripts/Fluent/master/Addons/InterfaceManager.lua"

local Players           = game:GetService("Players")
local TeleportService   = game:GetService("TeleportService")
local MarketplaceService = game:GetService("MarketplaceService")
local HttpService       = game:GetService("HttpService")

local genv = (getgenv and getgenv()) or _G

--=========================================================================
-- Environment / game detection
--=========================================================================
local function getExecutorName()
    local ok, name = pcall(function()
        return identifyexecutor and identifyexecutor() or nil
    end)
    if ok and type(name) == "string" and name ~= "" then
        return name
    end
    return "Unknown"
end

local function getGameInfo()
    local info = {
        PlaceId = game.PlaceId,
        GameId  = game.GameId,
        JobId   = game.JobId,
        Name    = "Unknown game",
    }

    local ok, product = pcall(function()
        return MarketplaceService:GetProductInfo(game.PlaceId)
    end)
    if ok and type(product) == "table" and product.Name then
        info.Name = product.Name
    end

    return info
end

--=========================================================================
-- Registry matching
--
-- Priority: PlaceIds (exact) -> GameIds (universe) -> NameMatch (substring
-- of the marketplace name, lowercased). NameMatch means a new game works
-- before you have had a chance to write the id down.
--=========================================================================
local function matchesEntry(entry, info)
    if entry.Universal then return false end

    if entry.PlaceIds then
        for _, id in ipairs(entry.PlaceIds) do
            if tonumber(id) == info.PlaceId then return true, "PlaceId" end
        end
    end

    if entry.GameIds then
        for _, id in ipairs(entry.GameIds) do
            if tonumber(id) == info.GameId then return true, "GameId" end
        end
    end

    if entry.NameMatch and info.Name then
        local needle = tostring(entry.NameMatch):lower()
        if needle ~= "" and string.find(info.Name:lower(), needle, 1, true) then
            return true, "Name"
        end
    end

    return false
end

local function resolve(registry, info)
    local matched, universal = {}, {}
    for _, entry in ipairs(registry) do
        if entry.Universal then
            universal[#universal + 1] = entry
        else
            local hit, how = matchesEntry(entry, info)
            if hit then
                entry._matchedBy = how
                matched[#matched + 1] = entry
            end
        end
    end
    return matched, universal
end

--=========================================================================
-- Start
--=========================================================================
function Core.Start(config)
    local hub = {
        Config    = config,
        GameInfo  = getGameInfo(),
        Executor  = getExecutorName(),
        Unloaded  = false,
        _cleanup  = {},
        _threads  = {},
        _conns    = {},
        _loaded   = {},
    }

    ----------------------------------------------------------------- cleanup
    function hub.OnUnload(fn)
        hub._cleanup[#hub._cleanup + 1] = fn
    end

    function hub.Connect(signal, fn)
        local conn = signal:Connect(fn)
        hub._conns[#hub._conns + 1] = conn
        return conn
    end

    function hub.Spawn(fn, ...)
        local thread = task.spawn(fn, ...)
        hub._threads[#hub._threads + 1] = thread
        return thread
    end

    ----------------------------------------------------------------- UI boot
    local Fluent = loadstring(game:HttpGet(FLUENT_URL))()

    local SaveManager, InterfaceManager
    pcall(function() SaveManager      = loadstring(game:HttpGet(SAVEMGR_URL))() end)
    pcall(function() InterfaceManager = loadstring(game:HttpGet(INTERFACE_URL))() end)

    hub.Fluent = Fluent

    function hub.Notify(content, duration, title)
        Fluent:Notify({
            Title    = title or config.Name,
            Content  = tostring(content),
            Duration = duration or 4,
        })
    end

    local Window = Fluent:CreateWindow({
        Title       = config.Name .. " " .. (config.Version or ""),
        SubTitle    = hub.GameInfo.Name,
        TabWidth    = 160,
        Size        = UDim2.fromOffset(580, 460),
        Acrylic     = true,
        Theme       = "Dark",
        MinimizeKey = Enum.KeyCode.LeftControl,
    })
    hub.Window  = Window
    hub.Options = Fluent.Options
    hub.Tabs    = {}

    function hub.AddTab(title, icon)
        local tab = Window:AddTab({ Title = title, Icon = icon or "box" })
        hub.Tabs[title] = tab
        return tab
    end

    ----------------------------------------------------------------- unload
    function hub.Unload()
        if hub.Unloaded then return end
        hub.Unloaded = true

        for _, fn in ipairs(hub._cleanup) do pcall(fn) end
        for _, conn in ipairs(hub._conns) do pcall(function() conn:Disconnect() end) end
        for _, thread in ipairs(hub._threads) do pcall(task.cancel, thread) end

        pcall(function() Fluent:Destroy() end)
        genv.__ScriptHub = nil
    end

    genv.__ScriptHub = hub

    ----------------------------------------------------------------- modules
    local registry = HUB_REQUIRE("src/registry")
    local matched, universal = resolve(registry, hub.GameInfo)

    local function runEntry(entry)
        local tabTitle = entry.Name or "Script"
        local ctx = {
            Hub      = hub,
            Fluent   = Fluent,
            Window   = Window,
            Options  = Fluent.Options,
            GameInfo = hub.GameInfo,
            Entry    = entry,
            Tab      = hub.AddTab(tabTitle, entry.Icon or "play"),
            Notify   = hub.Notify,
            Connect  = hub.Connect,
            Spawn    = hub.Spawn,
            OnUnload = hub.OnUnload,
        }
        function ctx.IsAlive() return not hub.Unloaded end

        local ok, mod = pcall(HUB_REQUIRE, entry.Module)
        if not ok then
            ctx.Tab:AddParagraph({ Title = "Failed to download", Content = tostring(mod) })
            hub.Notify("Could not load " .. tabTitle, 6)
            return false
        end

        local ranOk, err = pcall(mod.Setup, ctx)
        if not ranOk then
            ctx.Tab:AddParagraph({ Title = "Script error", Content = tostring(err) })
            hub.Notify(tabTitle .. " errored: " .. tostring(err), 8)
            return false
        end

        hub._loaded[#hub._loaded + 1] = entry
        return true
    end

    for _, entry in ipairs(matched) do runEntry(entry) end
    for _, entry in ipairs(universal) do runEntry(entry) end

    ----------------------------------------------------------------- hub tab
    local HubTab = hub.AddTab("Hub", "settings")

    if #matched == 0 then
        HubTab:AddParagraph({
            Title   = "No script for this game (yet)",
            Content = ("%s\nPlaceId: %d\nGameId: %d\n\nSend the PlaceId over and it can be added to the registry.")
                :format(hub.GameInfo.Name, hub.GameInfo.PlaceId, hub.GameInfo.GameId),
        })
    else
        local names = {}
        for _, entry in ipairs(matched) do
            names[#names + 1] = ("%s  (matched by %s)"):format(entry.Name, entry._matchedBy or "?")
        end
        HubTab:AddParagraph({
            Title   = "Loaded for this game",
            Content = table.concat(names, "\n"),
        })
    end

    HubTab:AddParagraph({
        Title   = "Environment",
        Content = ("Game: %s\nPlaceId: %d\nGameId: %d\nExecutor: %s\nHub: %s %s")
            :format(hub.GameInfo.Name, hub.GameInfo.PlaceId, hub.GameInfo.GameId,
                    hub.Executor, config.Name, config.Version or ""),
    })

    HubTab:AddButton({
        Title       = "Copy PlaceId",
        Description = "Puts this game's PlaceId on your clipboard",
        Callback    = function()
            if setclipboard then
                setclipboard(tostring(hub.GameInfo.PlaceId))
                hub.Notify("PlaceId copied: " .. hub.GameInfo.PlaceId)
            else
                hub.Notify("This executor has no setclipboard - PlaceId is " .. hub.GameInfo.PlaceId, 8)
            end
        end,
    })

    HubTab:AddButton({
        Title       = "Rejoin",
        Description = "Teleport back into this place",
        Callback    = function()
            pcall(function()
                TeleportService:Teleport(game.PlaceId, Players.LocalPlayer)
            end)
        end,
    })

    HubTab:AddButton({
        Title       = "Unload hub",
        Description = "Closes the UI and stops every loaded script",
        Callback    = function() hub.Unload() end,
    })

    -- Fluent's own config/interface panels, if the addons downloaded.
    pcall(function()
        InterfaceManager:SetLibrary(Fluent)
        SaveManager:SetLibrary(Fluent)
        SaveManager:IgnoreThemeSettings()
        SaveManager:SetIgnoreIndexes({})
        InterfaceManager:SetFolder(config.Name)
        SaveManager:SetFolder(config.Name .. "/" .. tostring(hub.GameInfo.PlaceId))
        InterfaceManager:BuildInterfaceSection(HubTab)
        SaveManager:BuildConfigSection(HubTab)
        SaveManager:LoadAutoloadConfig()
    end)

    Window:SelectTab(1)

    if #matched == 0 then
        hub.Notify("No script for " .. hub.GameInfo.Name .. " yet", 6)
    else
        hub.Notify(("Loaded %d script%s for %s"):format(
            #hub._loaded, #hub._loaded == 1 and "" or "s", hub.GameInfo.Name), 5)
    end

    return hub
end

return Core
]=]
__sources["src/registry"] = [=[
--[[
    Script Hub - registry
    =====================
    The only file you edit when adding a game.

    Entry fields
    ------------
    Name        required  tab title + display name
    Module      required  path passed to HUB_REQUIRE, no .lua extension
    PlaceIds    list of place ids this script is for (most specific match)
    GameIds     list of universe ids - catches every place in a universe
                (lobby + maps), use when a game teleports players around
    NameMatch   lowercase substring of the marketplace name; a safety net so
                a script still loads before you have written the id down
    Universal   true = always load, in every game
    Icon        lucide icon name for the tab
    Author      credit shown in the Hub tab
    Description free text

    Matching order is PlaceIds -> GameIds -> NameMatch. Several entries may
    match at once; each one gets its own tab.
]]

return {
    {
        Name        = "Spelling Race",
        Module      = "src/scripts/spelling_race",
        -- TODO: paste the real id here (Hub tab -> Copy PlaceId while in game)
        PlaceIds    = {},
        GameIds     = {},
        NameMatch   = "spelling race",
        Icon        = "book-a",
        Author      = "light2light (deobfuscated)",
        Description = "Decodes the round's word from the hidden attribute and auto-submits it.",
    },

    {
        Name        = "Universal",
        Module      = "src/scripts/universal",
        Universal   = true,
        Icon        = "globe",
        Author      = "hub",
        Description = "Server tools that work anywhere.",
    },

    --[[  template - copy this block for each new script

    {
        Name        = "Game Name",
        Module      = "src/scripts/game_name",
        PlaceIds    = { 1234567890 },
        GameIds     = {},
        NameMatch   = "game name",
        Icon        = "play",
        Author      = "original author",
        Description = "what it does",
    },

    ]]
}
]=]
__sources["src/scripts/spelling_race"] = [=[
--[[
    Spelling Race - auto spell
    ==========================
    Deobfuscated from "auto spell keyless.txt" (WeAreDevs obfuscator v1.0.0,
    original by light2light) and adapted to the hub module contract.

    How the game hides the answer, innermost first:
      1. the word is turned into ASCII codes
      2. each code has its DIGITS REVERSED          ("a" = 97 -> "79")
      3. codes are joined with commas
      4. every byte is XOR'd with a repeating key:  "1144" .. PlaceId .. "00552002"
      5. the result lives in the "Color" attribute of the Texture under a
         scenery part in workspace.Floors2
      6. Lighting.Bloom.Sky.StarCount is a per-round offset subtracted from
         every character code

    If the payload is missing or unusable the script falls back to the first
    non-empty AnswerControl.Answer1..4 value, exactly like the original.
]]

local M = {}

local HIDDEN_PART = "Part +R2107+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R21+ +R22+2"

function M.Setup(ctx)
    local ReplicatedStorage = game:GetService("ReplicatedStorage")

    local RoundControl = ReplicatedStorage:WaitForChild("RoundControlFolder", 10)
    local Remotes      = ReplicatedStorage:WaitForChild("Remotes", 10)
    if not (RoundControl and Remotes) then
        ctx.Tab:AddParagraph({
            Title   = "Not in a round yet",
            Content = "RoundControlFolder / Remotes were not found. Rejoin once a match is running and re-execute.",
        })
        return
    end

    local TopicControl  = RoundControl:WaitForChild("TopicControl", 10)
    local AnswerControl = RoundControl:WaitForChild("AnswerControl", 10)
    local SubmitAnswer  = Remotes:WaitForChild("SubmitAnswerRemote", 10)
    local TopicDesc     = TopicControl and TopicControl:WaitForChild("TopicDesc", 10)

    if not (TopicDesc and AnswerControl and SubmitAnswer) then
        ctx.Tab:AddParagraph({
            Title   = "Game layout changed",
            Content = "TopicDesc / AnswerControl / SubmitAnswerRemote missing - the script needs updating.",
        })
        return
    end

    --------------------------------------------------------------- settings
    local settings = {
        autoSpell   = true,
        answerDelay = 2.2,
        randomize   = true,
        notify      = true,
    }

    local function say(text, duration)
        if settings.notify then
            ctx.Notify(text, duration or 3, "Spelling Race")
        end
    end

    --------------------------------------------------------------- decoding
    local function readPayload()
        local floors = workspace:FindFirstChild("Floors2")
        if not floors then return nil end

        local part = floors:FindFirstChild(HIDDEN_PART)
        if not part then return nil end

        local texture = part:FindFirstChildOfClass("Texture")
        if not texture then return nil end

        return texture:GetAttribute("Color")
    end

    local function decodeWord()
        local payload = readPayload()
        if not payload or payload == "" then return nil end

        -- undo the XOR; bytes that come out as letters are corrupt and
        -- collapse into the "," separator so they drop out of the split
        local key   = "1144" .. game.PlaceId .. "00552002"
        local plain = {}
        for i = 1, #payload do
            local b = bit32.bxor(payload:byte(i), key:byte((i - 1) % #key + 1))
            if (b >= 65 and b <= 90) or (b >= 97 and b <= 122) then
                b = 44
            end
            plain[i] = string.char(b)
        end

        local offset = 0
        pcall(function()
            offset = game.Lighting.Bloom.Sky.StarCount
        end)

        local word = ""
        for _, chunk in ipairs(string.split(table.concat(plain), ",")) do
            local code = tonumber(string.reverse(chunk))
            if code then
                code = code - offset
                if code >= 32 and code <= 126 then
                    word = word .. string.char(code)
                end
            end
        end

        if word ~= "" then return word end
        return nil
    end

    local function fallbackAnswer()
        for i = 1, 4 do
            local answer = AnswerControl:FindFirstChild("Answer" .. i)
            local value  = answer and answer.Value or ""
            if value ~= "" then return value end
        end
        return ""
    end

    --------------------------------------------------------------- submitting
    local function submit(word, elapsed)
        -- the trailing two spaces are part of what the original sends
        local ok, result = pcall(function()
            return SubmitAnswer:InvokeServer(word .. "  ", "keyboard", nil, elapsed)
        end)
        if not ok then
            say("Submit failed: " .. tostring(result), 6)
            return nil
        end

        if result then
            if result.correct then
                say("Correct! +" .. tostring(result.score))
            elseif result.closeAnswer then
                say("Close! +" .. tostring(result.score))
            else
                say("Wrong: " .. tostring(result.correctAnswer or "?"))
            end
        end
        return result
    end

    local function currentWord()
        local word
        for _ = 1, 5 do
            if not ctx.IsAlive() then return nil end
            word = decodeWord()
            if word then return word end
            task.wait(0.5)
        end
        return nil
    end

    local busy = false

    local function solveRound()
        if busy or not ctx.IsAlive() or not settings.autoSpell then return end
        busy = true

        say("Loading word...")
        task.wait(1)

        local word = currentWord() or fallbackAnswer()
        if word == "" or not ctx.IsAlive() then
            busy = false
            return
        end

        say("Word: " .. word)

        local delay = settings.answerDelay
        if settings.randomize then
            delay = delay + (math.random() - 0.5) -- +/- 0.5s jitter
        end
        task.wait(delay)

        if ctx.IsAlive() and settings.autoSpell then
            say("Spelling...")
            submit(word, delay - 0.7)
        end
        busy = false
    end

    --------------------------------------------------------------- interface
    ctx.Tab:AddParagraph({
        Title   = "Spelling Race",
        Content = "Reads the round's word straight out of the game and answers it. "
               .. "Answer Time 2.2 with Randomize on looks the most human.",
    })

    local autoToggle = ctx.Tab:AddToggle("SpellingRace_AutoSpell", {
        Title   = "Auto Spell",
        Default = true,
    })
    autoToggle:OnChanged(function(value)
        settings.autoSpell = value
    end)

    ctx.Tab:AddSlider("SpellingRace_AnswerDelay", {
        Title       = "Answer Time",
        Description = "Delay before answering (seconds)",
        Default     = 2.2,
        Min         = 0.1,
        Max         = 5,
        Rounding    = 1,
        Callback    = function(value)
            settings.answerDelay = value
        end,
    })

    local randomToggle = ctx.Tab:AddToggle("SpellingRace_Randomize", {
        Title       = "Randomize Time",
        Description = "Adds up to +/- 0.5s of jitter",
        Default     = true,
    })
    randomToggle:OnChanged(function(value)
        settings.randomize = value
    end)

    local notifyToggle = ctx.Tab:AddToggle("SpellingRace_Notifications", {
        Title   = "Notifications",
        Default = true,
    })
    notifyToggle:OnChanged(function(value)
        settings.notify = value
    end)

    ctx.Tab:AddButton({
        Title       = "Spell Now",
        Description = "Answer the current word immediately",
        Callback    = function()
            ctx.Spawn(function()
                local word = decodeWord() or fallbackAnswer()
                if word == "" then
                    ctx.Notify("No word available yet", 4, "Spelling Race")
                    return
                end
                ctx.Notify("Spelling now...", 3, "Spelling Race")
                submit(word, 0.1)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Show decoded word",
        Description = "Peek at the answer without submitting",
        Callback    = function()
            local word = decodeWord()
            ctx.Notify(word and ("Word: " .. word) or "Payload not readable right now", 5, "Spelling Race")
        end,
    })

    --------------------------------------------------------------- run
    ctx.Connect(TopicDesc:GetPropertyChangedSignal("Value"), function()
        if TopicDesc.Value ~= "" then
            ctx.Spawn(solveRound)
        end
    end)

    if TopicDesc.Value ~= "" then
        ctx.Spawn(solveRound)
    end
end

return M
]=]
__sources["src/scripts/universal"] = [=[
--[[
    Universal tools
    ===============
    Loaded in every game (Universal = true in the registry). Keep this file
    for things that never depend on a specific place: server hopping, rejoin,
    FPS/ping readouts, character conveniences.

    It also doubles as the reference implementation of the module contract:
      Setup(ctx) with ctx.Tab / ctx.Notify / ctx.Connect / ctx.Spawn /
      ctx.OnUnload / ctx.IsAlive.
]]

local M = {}

function M.Setup(ctx)
    local Players         = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")
    local HttpService     = game:GetService("HttpService")
    local RunService      = game:GetService("RunService")
    local StarterGui      = game:GetService("StarterGui")

    local LocalPlayer = Players.LocalPlayer

    ctx.Tab:AddParagraph({
        Title   = "Server",
        Content = "Works in any game.",
    })

    ctx.Tab:AddButton({
        Title       = "Rejoin",
        Description = "Teleport back into this place",
        Callback    = function()
            pcall(function()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Server hop",
        Description = "Jump to another public server of this game",
        Callback    = function()
            ctx.Spawn(function()
                local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100")
                    :format(game.PlaceId)

                local ok, body = pcall(function()
                    return game:HttpGet(url)
                end)
                if not ok then
                    ctx.Notify("Server list request failed", 5)
                    return
                end

                local decoded
                ok, decoded = pcall(function() return HttpService:JSONDecode(body) end)
                if not ok or type(decoded) ~= "table" or not decoded.data then
                    ctx.Notify("Could not read the server list", 5)
                    return
                end

                for _, server in ipairs(decoded.data) do
                    if server.playing and server.maxPlayers
                        and server.playing < server.maxPlayers
                        and server.id ~= game.JobId then
                        ctx.Notify("Hopping...", 4)
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, server.id, LocalPlayer)
                        return
                    end
                end

                ctx.Notify("No other server with room", 5)
            end)
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Copy JobId",
        Description = "This server's instance id",
        Callback    = function()
            if setclipboard then
                setclipboard(game.JobId)
                ctx.Notify("JobId copied")
            else
                ctx.Notify("No setclipboard in this executor", 5)
            end
        end,
    })

    ------------------------------------------------------------------ player
    ctx.Tab:AddParagraph({ Title = "Character", Content = "" })

    ctx.Tab:AddSlider("Universal_WalkSpeed", {
        Title    = "WalkSpeed",
        Default  = 16,
        Min      = 16,
        Max      = 200,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = value end
        end,
    })

    ctx.Tab:AddSlider("Universal_JumpPower", {
        Title    = "JumpPower",
        Default  = 50,
        Min      = 50,
        Max      = 300,
        Rounding = 0,
        Callback = function(value)
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then
                hum.UseJumpPower = true
                hum.JumpPower    = value
            end
        end,
    })

    ctx.Tab:AddButton({
        Title       = "Reset character",
        Description = "Breaks joints on your humanoid",
        Callback    = function()
            local char = LocalPlayer.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            if hum then hum.Health = 0 end
        end,
    })

    ------------------------------------------------------------------ stats
    local statsParagraph = ctx.Tab:AddParagraph({
        Title   = "Stats",
        Content = "FPS: -   Ping: -",
    })

    ctx.Spawn(function()
        while ctx.IsAlive() do
            local fps, ping = "-", "-"
            pcall(function()
                local dt = RunService.RenderStepped:Wait()
                if type(dt) == "number" and dt > 0 then
                    fps = tostring(math.floor(1 / dt))
                end
            end)
            pcall(function()
                ping = math.floor(LocalPlayer:GetNetworkPing() * 1000) .. "ms"
            end)
            pcall(function()
                statsParagraph:SetDesc(("FPS: %s   Ping: %s"):format(fps, ping))
            end)
            task.wait(1)
        end
    end)
end

return M
]=]

local __cache = {}
local function __require(path)
    if __cache[path] ~= nil then return __cache[path] end
    local source = __sources[path]
    if not source then error('[Hub] unknown module: ' .. tostring(path), 0) end
    local chunk, err = loadstring(source, '@' .. path)
    if not chunk then error('[Hub] syntax error in ' .. path .. ': ' .. tostring(err), 0) end
    __cache[path] = chunk()
    return __cache[path]
end
genv.HUB_REQUIRE = __require
HUB_REQUIRE = __require

local CONFIG = {
    Name = "Nam Hub",
    Version = "1.0.0",
    BaseUrl = "",
    CacheBust = false,
    Debug = false,
}

return __require('src/core').Start(CONFIG)
